import csv

# Verify missingness counts
with open('outputs/t11_city_indicator_matrix.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    indicators = header[3:]

    indicator_counts = {ind: 0 for ind in indicators}
    total_cells = 0

    for row in reader:
        for i, ind in enumerate(indicators):
            if i < len(row) and row[i] == '':
                indicator_counts[ind] += 1
            total_cells += 1

    print('=== Verification ===')
    print(f'Total cells: {total_cells}')
    for ind in indicators:
        print(f'{ind}: {indicator_counts[ind]} missing out of {total_cells} cells, rate = {indicator_counts[ind]/total_cells:.6f}')
""}
